SELECT DISTINCT V.SQ_PESSOA_VINCULADA,V.SQ_PESSOA_VINCULANTE,PJV.SQ_PESSOA,P1.NO_PESSOA,P.SQ_PESSOA,P.NO_PESSOA FROM VINCULO V INNER JOIN PESSOA P ON V.SQ_PESSOA_VINCULANTE = P.SQ_PESSOA INNER JOIN PESSOA_JURIDICA PJ ON    V.SQ_PESSOA_VINCULANTE = PJ.SQ_PESSOA LEFT JOIN PESSOA_JURIDICA PJV ON    V.SQ_PESSOA_VINCULADA = PJV.SQ_PESSOA LEFT JOIN PESSOA P1 ON P1.SQ_PESSOA = PJV.SQ_PESSOA LEFT JOIN   MUNICIPIO M ON M.CO_MUNICIPIO = P.CO_MUNICIPIO LEFT JOIN SITUACAO S ON PJ.CO_SITUACAO = S.CO_SITUACAO LEFT JOIN   CONDICAO C ON V.CO_CONDICAO = C.CO_CONDICAO  WHERE C.IN_TIPO_TABELA = '1' AND PJV.NR_CGC = '11260429000134'  ORDER BY 	P.NO_PESSOA 



SELECT V.SQ_PESSOA_VINCULADA,(SELECT P.NO_PESSOA FROM PESSOA P WHERE P.SQ_PESSOA = V.SQ_PESSOA_VINCULADA) NO_PESSOA_VINCULADA,V.SQ_PESSOA_VINCULANTE,(SELECT P.NO_PESSOA FROM PESSOA P WHERE P.SQ_PESSOA = V.SQ_PESSOA_VINCULANTE) NO_PESSOA_VINCULANTE,
(SELECT PJ.NR_CGC FROM PESSOA_JURIDICA PJ WHERE PJ.SQ_PESSOA = V.SQ_PESSOA_VINCULANTE) NR_CGC_VINCULANTE
  FROM VINCULO V LEFT JOIN CONDICAO C ON V.CO_CONDICAO = C.CO_CONDICAO 
WHERE V.SQ_PESSOA_VINCULANTE IN (SELECT PJ.SQ_PESSOA FROM PESSOA_JURIDICA PJ) AND C.IN_TIPO_TABELA = '1'

